@ vpy_wait_recal() — BIOS trap: SYS_WAIT_RECAL
.global vpy_wait_recal
.type vpy_wait_recal, %function
.thumb_func
vpy_wait_recal:
    svc     #1                      @ SYS_WAIT_RECAL
    bx      lr

@ vpy_set_intensity(r0=intensity 0-127) — BIOS trap: SYS_SET_INTENSITY
.global vpy_set_intensity
.type vpy_set_intensity, %function
.thumb_func
vpy_set_intensity:
    svc     #2                      @ SYS_SET_INTENSITY
    bx      lr

@ vpy_draw_line(r0=x0, r1=y0, r2=x1, r3=y1, [sp+0]=intensity)
@ Splits segments longer than 127 units using SDIV for proportional steps
.global vpy_draw_line
.type vpy_draw_line, %function
.thumb_func
vpy_draw_line:
    push    {r4, r5, r6, r7, r8, lr}
    mov     r4, r0
    mov     r5, r1
    mov     r6, r2
    mov     r7, r3
    ldr     r2, =VPY_MOVE_X
    ldr     r3, [r2]            @ r3 = VPY_MOVE_X
    ldr     r2, [r2, #4]        @ r2 = VPY_MOVE_Y
    add     r4, r4, r3          @ x0 += MOVE_X
    add     r5, r5, r2          @ y0 += MOVE_Y
    add     r6, r6, r3          @ x1 += MOVE_X
    add     r7, r7, r2          @ y1 += MOVE_Y
    ldr     r8, [sp, #24]           @ intensity (5th arg, past 6 saved regs)
    bl      dv_reset
    mov     r0, r8
    bl      vpy_set_intensity
    mov     r0, r4
    mov     r1, r5
    bl      dv_move_to
    sub     r4, r6, r4
    sub     r5, r7, r5
    movs    r6, r4
    bpl     vdl_dx_pos
    neg     r6, r4
vdl_dx_pos:
    movs    r7, r5
    bpl     vdl_dy_pos
    neg     r7, r5
vdl_dy_pos:
    cmp     r6, r7
    it      ge
    movge   r7, r6
    cmp     r7, #0
    beq     vdl_done
    add     r7, r7, #126
    mov     r6, #127
    sdiv    r8, r7, r6
vdl_loop:
    cmp     r8, #0
    beq     vdl_done
    sdiv    r0, r4, r8
    sdiv    r1, r5, r8
    sub     r4, r4, r0
    sub     r5, r5, r1
    sub     r8, r8, #1
    bl      dv_draw_delta
    b       vdl_loop
vdl_done:
    pop     {r4, r5, r6, r7, r8, pc}
    .ltorg

@ vpy_print_text(r0=x, r1=y, r2=str_ptr)
.global vpy_print_text
.type vpy_print_text, %function
.thumb_func
vpy_print_text:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}
    mov     r4, r0
    mov     r5, r1
    mov     r6, r2
    ldr     r7, =TEXT_SIZE
    ldr     r7, [r7]
    cmp     r7, #0
    bne     vpt_sc
    mov     r7, #3
vpt_sc:
    ldr     r8, =TEXT_COLOR
    ldr     r8, [r8]
    cmp     r8, #0
    bne     vpt_cc
    mov     r8, #100
vpt_cc:
    bl      dv_reset
    mov     r0, r8
    bl      vpy_set_intensity
    mov     r0, #6
    mul     r0, r0, r7
    asr     r0, r0, #1
    sub     r5, r5, r0
    mov     r0, r4
    mov     r1, r5
    bl      dv_move_to
    ldr     r10, =PRINT_BEAM_X
    str     r4, [r10]
    ldr     r11, =PRINT_BEAM_Y
    str     r5, [r11]
    mov     r9, r4              @ cur_x = x
vpt_loop:
    ldrb    r0, [r6]
    add     r6, r6, #1
    cmp     r0, #0
    beq     vpt_done
    cmp     r0, #0x80
    beq     vpt_done
    cmp     r0, #0x61
    blt     vpt_nl
    cmp     r0, #0x7A
    bgt     vpt_nl
    sub     r0, r0, #0x20
vpt_nl:
    cmp     r0, #32
    blt     vpt_adv
    cmp     r0, #126
    bgt     vpt_adv
    sub     r0, r0, #32
    ldr     r1, =_FONT_PTRS
    lsl     r0, r0, #2
    ldr     r0, [r1, r0]
    cmp     r0, #0
    beq     vpt_adv
    mov     r1, r9
    mov     r2, r5
    mov     r3, r7
    push    {r10, r11}
    bl      vpt_draw_glyph
    add     sp, sp, #8
vpt_adv:
    mov     r0, #7
    mul     r0, r0, r7
    asr     r0, r0, #1
    add     r9, r9, r0
    b       vpt_loop
vpt_done:
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

@ vpt_draw_glyph — internal: draw one glyph at (char_x, char_y) with scale
.type vpt_draw_glyph, %function
.thumb_func
vpt_draw_glyph:
    push    {r4, r5, r6, r7, r8, r9, r10, r11, lr}
    mov     r4, r0              @ glyph_ptr
    mov     r5, r1              @ char_x
    mov     r6, r2              @ char_y
    mov     r7, r3              @ scale
    ldr     r8, [sp, #36]       @ bx_ptr (PRINT_BEAM_X)
    ldr     r9, [sp, #40]       @ by_ptr (PRINT_BEAM_Y)
    ldr     r10, [r8]           @ beam_x
    ldr     r11, [r9]           @ beam_y
vdg_loop:
    ldrb    r0, [r4]
    cmp     r0, #0
    beq     vdg_done
    ldrb    r1, [r4, #1]        @ gx
    ldrb    r2, [r4, #2]        @ gy
    add     r4, r4, #3
    push    {r0}               @ save cmd
    mul     r1, r1, r7
    asr     r1, r1, #1
    add     r1, r1, r5
    mul     r2, r2, r7
    asr     r2, r2, #1
    add     r2, r2, r6
    sub     r0, r1, r10         @ dx
    sub     r3, r2, r11         @ dy
    mov     r10, r1
    mov     r11, r2
    pop     {r1}               @ restore cmd
    push    {r0, r3}           @ save dx, dy
    cmp     r1, #1
    bne     vdg_draw
    pop     {r0, r1}
    bl      dv_move_to
    b       vdg_loop
vdg_draw:
    pop     {r0, r1}
    bl      dv_draw_delta
    b       vdg_loop
vdg_done:
    str     r10, [r8]           @ update PRINT_BEAM_X
    str     r11, [r9]           @ update PRINT_BEAM_Y
    pop     {r4, r5, r6, r7, r8, r9, r10, r11, pc}
    .ltorg

